import subprocess, sys

try:
    subprocess.run([sys.executable, "-c", "import sys; print('boom', file=sys.stderr); sys.exit(2)"],
                   check=True, capture_output=True, text=True)
except subprocess.CalledProcessError as e:
    print("exit", e.returncode, "stderr:", e.stderr.strip())   # exit 2 stderr: boom

try:
    subprocess.run(["no-such-tool", "--version"])
except FileNotFoundError as e:
    print("missing:", e.filename)                             # missing: no-such-tool

r = subprocess.run(["grep", "x"], input="abc\n", text=True, capture_output=True)
print("grep found nothing" if r.returncode == 1 else "match")  # grep found nothing
